children.code:
// a rounded slab, offset to the right of the ball
let q = p - VEC3(1.5, 0.0, 0.0);
C = add_new(C, sdRoundedBox(q, size, bevel), MATERIAL);

// the base of the Carved group: its first child, so the ball below is cut out of it
// sdRoundedBox(point, half-size, corner radius)
C = add_new(C, sdRoundedBox(p, VEC3(0.8), 0.05), MATERIAL);

// Twist about z: "rate" radians per unit of height. Costs a sin and a cos per step.
// A twist stretches space, the more the farther from the axis; "extent" -- how far the
// children reach from it -- sets the step scale that keeps the march from overshooting.
let a = rate * p.z;
p = VEC3(cos(a) * p.x - sin(a) * p.y, sin(a) * p.x + cos(a) * p.y, p.z);
warp(1.0 / sqrt(1.0 + rate * rate * extent * extent));
C = children(C, p);

// Code node: fold shapes into C.  C = add_new(C, <sdf>, MATERIAL);
//   p         the point, in this node's own frame (its transform is already applied)
//   MATERIAL  this node's material;  parameters are in scope by name
//   an sdf is VEC4(normal.xyz, distance); sd(d) wraps a bare distance (normal then computed)
// e.g. a rounded box:     C = add_new(C, sdRoundedBox(p, VEC3(0.5), 0.05), MATERIAL);
// e.g. a plane, z up:     C = add_new(C, VEC4(0.0, 0.0, 1.0, p.z), MATERIAL);
// e.g. two shapes merged: C = add_new(C, csgUnion(Nsphere(p, 0.5), sdBox(p - VEC3(0.6, 0.0, 0.0), VEC3(0.3)), 0.2), MATERIAL);
C = add_new(C, sdBox(p, VEC3(0.5)), MATERIAL);

